305	fn strip_ansi(input: &str) -> String {
306	    let mut output = String::new();
307	    let mut chars = input.chars();
308	    while let Some(ch) = chars.next() {
309	        if ch == '\u{1b}' {
310	            for next in chars.by_ref() {
311	                if next.is_ascii_alphabetic() {
312	                    break;
313	                }
314	            }
315	        } else {
316	            output.push(ch);
317	        }
318	    }
319	    output
320	}

