536	fn strip_ansi(input: &str) -> String {
537	    let mut output = String::new();
538	    let mut chars = input.chars();
539	    while let Some(ch) = chars.next() {
540	        if ch == '\u{1b}' {
541	            for next in chars.by_ref() {
542	                if next.is_ascii_alphabetic() {
543	                    break;
544	                }
545	            }
546	        } else {
547	            output.push(ch);
548	        }
549	    }
550	    output
551	}

