 750	    fn command_mode_text_key_control_status(&self, key: UiKey) -> Option<bool> {
 751	        if self.mode != UiMode::Command || self.pending.is_some() {
 752	            return None;
 753	        }
 754	        let UiKey::Char(ch) = key else {
 755	            return None;
 756	        };
 757	        (ch.is_ascii_alphanumeric() || ch == ' ').then(|| self.is_command_control_char(ch))
 758	    }
