 760	    fn is_command_control_char(&self, ch: char) -> bool {
 761	        matches!(ch, 'i' | ':' | ',' | 's' | 't' | 'f' | 'g')
 762	            || (self.focus == PaneFocus::Left && matches!(ch, 'j' | 'k' | 'l' | 'x'))
 763	    }
