 858	            return Vec::new();
 859	        }
 860	
 861	        let left_width = self.layout().left_width;
 862	
 863	        if self.left_visible && column <= left_width {
 864	            self.mode = UiMode::Command;
 865	            self.focus = PaneFocus::Left;
 866	            let Some(target) = self.left_pane_click_target(row) else {
