 872	                    self.focus = PaneFocus::Right;
 873	                }
 874	                LeftPaneClickTarget::Agent(agent_id) => {
 875	                    let _ = self.activate_agent_chat(&agent_id);
 876	                }
 877	            }
 878	        } else {
 879	            self.focus = PaneFocus::Right;
 880	            self.mode = if self.selected_agent.is_some()
 881	                && self.windows[self.active_window].surface == UiSurface::AgentChat
 882	            {
 883	                UiMode::Insert
